with valid_transactions as (select * from transactions where amount > 1600 or amount between 2100 and 2200), Summary as (select account_id, merchant, count(distinct amount) as unique_merchants, min(txn_time) as first_txn_time from valid_transactions group by account_id, merchant) select account_id, merchant, unique_merchants, first_txn_time from Summary order by merchant desc, account_id limit 5
